CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email citext UNIQUE NOT NULL, display_name varchar(160) NOT NULL, password_hash text NOT NULL, is_active boolean NOT NULL DEFAULT true, failed_login_count integer NOT NULL DEFAULT 0, locked_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug varchar(64) UNIQUE NOT NULL, name varchar(120) NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug varchar(120) UNIQUE NOT NULL, name varchar(160) NOT NULL);
CREATE TABLE IF NOT EXISTS user_roles (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS universities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(200) NOT NULL, code varchar(50) UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS faculties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), university_id uuid NOT NULL REFERENCES universities(id), name varchar(200) NOT NULL, code varchar(50) NOT NULL, UNIQUE(university_id,code));
CREATE TABLE IF NOT EXISTS departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), faculty_id uuid NOT NULL REFERENCES faculties(id), name varchar(200) NOT NULL, code varchar(50) NOT NULL, UNIQUE(faculty_id,code));
CREATE TABLE IF NOT EXISTS courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), department_id uuid REFERENCES departments(id), code varchar(50) UNIQUE NOT NULL, title varchar(200) NOT NULL, credits integer NOT NULL DEFAULT 3 CHECK(credits>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS students (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, student_number varchar(80) UNIQUE NOT NULL, department_id uuid REFERENCES departments(id), year_level integer CHECK(year_level BETWEEN 1 AND 8));
CREATE TABLE IF NOT EXISTS instructors (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, employee_number varchar(80) UNIQUE NOT NULL, department_id uuid REFERENCES departments(id));
CREATE TYPE exam_status AS ENUM ('draft','scheduled','active','closed','archived');
CREATE TABLE IF NOT EXISTS exams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by uuid NOT NULL REFERENCES users(id), course_id uuid REFERENCES courses(id), course_code varchar(50), title varchar(240) NOT NULL, instructions text NOT NULL DEFAULT '', status exam_status NOT NULL DEFAULT 'draft', duration_minutes integer NOT NULL CHECK(duration_minutes BETWEEN 1 AND 1440), attempt_limit integer NOT NULL DEFAULT 1 CHECK(attempt_limit>0), negative_marking numeric(8,3) NOT NULL DEFAULT 0 CHECK(negative_marking>=0), randomize_questions boolean NOT NULL DEFAULT false, randomize_options boolean NOT NULL DEFAULT false, start_at timestamptz, end_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS question_bank (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), course_id uuid REFERENCES courses(id), name varchar(200) NOT NULL, description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TYPE question_type AS ENUM ('multiple_choice','multiple_select','true_false','short_answer','essay');
CREATE TABLE IF NOT EXISTS questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bank_id uuid REFERENCES question_bank(id) ON DELETE SET NULL, author_id uuid NOT NULL REFERENCES users(id), type question_type NOT NULL, prompt text NOT NULL, explanation text NOT NULL DEFAULT '', difficulty varchar(20) NOT NULL DEFAULT 'medium', points numeric(8,3) NOT NULL DEFAULT 1 CHECK(points>0), tags jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS question_options (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES questions(id) ON DELETE CASCADE, option_key varchar(10) NOT NULL, option_text text NOT NULL, is_correct boolean NOT NULL DEFAULT false, UNIQUE(question_id,option_key));
CREATE TABLE IF NOT EXISTS exam_questions (exam_id uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES questions(id), position integer NOT NULL CHECK(position>0), points numeric(8,3) NOT NULL CHECK(points>0), PRIMARY KEY(exam_id,question_id), UNIQUE(exam_id,position));
CREATE TABLE IF NOT EXISTS exam_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_id uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE, cohort_label varchar(160), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, created_by uuid NOT NULL REFERENCES users(id), CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS exam_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_id uuid NOT NULL REFERENCES exams(id), student_id uuid NOT NULL REFERENCES users(id), scheduled_id uuid REFERENCES exam_schedules(id), started_at timestamptz, submitted_at timestamptz, server_deadline timestamptz, status varchar(30) NOT NULL DEFAULT 'assigned', UNIQUE(exam_id,student_id));
CREATE TABLE IF NOT EXISTS exam_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES exam_sessions(id) ON DELETE CASCADE, attempt_number integer NOT NULL DEFAULT 1, status varchar(30) NOT NULL DEFAULT 'in_progress', started_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz, score numeric(10,3), percentage numeric(6,3), grade varchar(10), UNIQUE(session_id,attempt_number));
CREATE TABLE IF NOT EXISTS student_answers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES exam_attempts(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES questions(id), values jsonb NOT NULL DEFAULT '[]', saved_at timestamptz NOT NULL DEFAULT now(), UNIQUE(attempt_id,question_id));
CREATE TABLE IF NOT EXISTS results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid UNIQUE NOT NULL REFERENCES exam_attempts(id), score numeric(10,3) NOT NULL, maximum numeric(10,3) NOT NULL, percentage numeric(6,3) NOT NULL, grade varchar(10), published_at timestamptz, instructor_comment text, overridden_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS proctoring_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid UNIQUE NOT NULL REFERENCES exam_attempts(id), camera_permission boolean NOT NULL DEFAULT false, camera_verified_at timestamptz, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz);
CREATE TABLE IF NOT EXISTS proctoring_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), proctoring_session_id uuid NOT NULL REFERENCES proctoring_sessions(id) ON DELETE CASCADE, event_type varchar(80) NOT NULL, confidence numeric(5,4) CHECK(confidence BETWEEN 0 AND 1), occurred_at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}', reviewed_at timestamptz, reviewed_by uuid REFERENCES users(id), reviewer_note text);
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), action varchar(80) NOT NULL, resource_type varchar(80), resource_id uuid, result varchar(30) NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', ip_hash varchar(128), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type varchar(80) NOT NULL, title varchar(240) NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS announcements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), author_id uuid NOT NULL REFERENCES users(id), title varchar(240) NOT NULL, body text NOT NULL, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, refresh_token_hash text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refresh_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS system_settings (key varchar(120) PRIMARY KEY, value jsonb NOT NULL, updated_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_exams_status_dates ON exams(status,start_at,end_at) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_audit_logs_created ON audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_proctoring_events_review ON proctoring_events(reviewed_at,occurred_at DESC);
INSERT INTO roles(slug,name) VALUES ('super_admin','Super Admin'),('university_admin','University Admin'),('instructor','Instructor'),('proctor','Proctor'),('student','Student') ON CONFLICT(slug) DO NOTHING;
